-- Restored-backup data of the v0.5 refusal fixture's db node (tools/tests,
-- v0.5 chunk 6): the load fixture's, with the order API's role.
CREATE ROLE shop NOLOGIN;
CREATE ROLE shop_app LOGIN;
CREATE ROLE lab_api LOGIN;
CREATE DATABASE shop OWNER shop;

\connect shop
SET ROLE shop;

CREATE TABLE customers (
    id   integer PRIMARY KEY,
    name text    NOT NULL
);

CREATE TABLE orders (
    id          integer       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id integer       NOT NULL REFERENCES customers (id),
    placed_at   timestamptz   NOT NULL,
    total       numeric(10,2) NOT NULL
);

INSERT INTO customers (id, name)
SELECT g, 'customer ' || g FROM generate_series(1, 500) AS g;

RESET ROLE;
GRANT SELECT, INSERT ON customers, orders TO shop_app, lab_api;
